{"content":""""Solve the Zebra Puzzle by assigning each attribute a house position."""

from functools import cache
from itertools import permutations


@cache
def _solve():
    """Return the nationalities of the water drinker and zebra owner."""
    orders = tuple(permutations(range(1, 6)))
    nationalities = ("Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese")

    for red, green, ivory, yellow, blue in orders:
        if green != ivory + 1 or blue != 2:
            continue

        for englishman, spaniard, ukrainian, norwegian, japanese in orders:
            if englishman != red or norwegian != 1:
                continue

            for coffee, tea, milk, orange_juice, water in orders:
                if coffee != green or tea != ukrainian or milk != 3:
                    continue

                for dancing, painting, reading, football, chess in orders:
                    if painting != yellow or football != orange_juice or chess != japanese:
                        continue

                    for dog, snails, fox, horse, zebra in orders:
                        if dog != spaniard or snails != dancing:
                            continue
                        if abs(reading - fox) != 1 or abs(painting - horse) != 1:
                            continue

                        residents = dict(zip(
                            (englishman, spaniard, ukrainian, norwegian, japanese),
                            nationalities,
                        ))
                        return residents[water], residents[zebra]

    raise ValueError("The puzzle has no solution")


def drinks_water():
    """Return the nationality of the resident who drinks water."""
    return _solve()[0]


def owns_zebra():
    """Return the nationality of the resident who owns the zebra."""
    return _solve()[1]
